import json,pathlib
R=[]
def add(f,m,o,a,l,start=None):
 d=dict(repo='AlexModGuy/AlexsMobs',file='/'+f+'.java',method=m,observation=o,application=a,limits=l)
 if start:d['start']=start
 R.append(d)
add('EntityKangaroo','registerGoals','坐姿优先于近战；target只有主人受击/攻击和AnimalAIHurtByTargetNotBaby，后者区分幼体报复及呼援。','幼体即使不直接参战仍可传播目标；审查不能只检查成年宠物近战goal。','近似OwnerHurt列表不按物种再计，本条相关贡献为幼体伤害呼援路径挂载。')
add('AnimalAIHurtByTargetNotBaby','start','父报复start先执行，若动物是幼体则alertOthers后stop。','停止幼体报复发生在父start之后，父赋target/呼援副作用须一起检查。','该goal实际被Kangaroo/Hawk注册；不是只从孤立未调用方法计数。')
add('AnimalAIHurtByTargetNotBaby','alertOther','只给非幼体候选调用父类alertOther，幼体候选不接收援助target。','群体转发要对接收者施许可，不能只在发起者检查。','单个年龄门是具体呼援策略，不将各物种注册成重复实现。')
add('EntityKomodoDragon','registerGoals','除主人事件和受伤报复，还主动选同类受伤/幼体、Player及tag食谱活体，跟随/诱惑/争斗等并存。','可驯服敌对生物仍可能保留最近玩家扫描，需追目标过滤及实际驯服状态门。','不凭注册片段判定已复现宠物攻击玩家；需继续看父canAttack和Tamable关系。')
add('EntityKomodoDragon','doHurtTarget','父近战成功后才按难度给Living目标5/10/20秒毒；失败false无毒。','攻击失败是否仍加状态必须逐处读，此例将后效绑定成功结果。','只计伤害许可与后效顺序，不把难度对应数值当多个参考。')
add('EntityKomodoDragon','setTarget','只有非幼体或slaughterCooldown>0才调用父setTarget，拒绝分支连null清理也不转发。','目标赋值门要允许撤销null，否则状态改变后旧目标可能清不掉。','是否能幼体持旧target需实际生命周期；不将局部条件冒称已复现bug。')
add('EntityMimicOctopus','registerGoals','攻击goal最高优先，其次坐/水跟随；主人受击攻击都可选敌，自身HurtBy匿名canUse额外要求已驯服。','野生和受控报复可在目标goal启动处分流，保留两种原机制而不改全局PVP。','整个匿名goal随注册计一处；不可把通用OwnerHurt端口重复算数。')
add('EntityMimicOctopus','mobInteract','驯服后物品可切模仿/锁状态/升级/装桶，不同分支未要求owner；末尾持物交换与命令切换才要求isOwnedBy。','控制入口权限不一定统一，不能看到末尾owner门就推定前面全部动作也受它保护。','这些分支或为设计允许喂养，不宣称漏洞；本项目无新增模仿或桶拾取机制。')
add('EntityMimicOctopus','canUse','AIAttack冷却>0先清同步激光ID并递减，锁定OVERLAY状态直接拒绝，其他需冷却0/驯服/活目标。','一次goal探测也可能有清状态副作用；冷却和目标生效必须基于真实调用频次。','不将此减计数直接解释为每server tick固定下降，goal canUse调度需按原生版本。',1124)
add('EntityMimicOctopus','stop','清恐吓位置/时间，普通冷却100至299，升级改30；未升级还清受击者及target，升级保留；按状态恢复环境模仿，清激光ID。','同一stop对不同能力阶段保留不同仇恨，换装/升级边界必须有针对性检查。','普通与升级分支只计一个完整方法；不照搬随机冷却到本项目。',1136)
add('EntityMimicOctopus','generateFleePosition','最多15次在受害者周围随机向下找地面；Pathfinder需walkTargetValue非负，其他Living直接接受位置。','强制敌方逃跑是攻击副作用，也应受目标许可；不能只防hurt生命值。','只计具体恐吓目标移动策略，采样次数和地形工具不另计。')
add('EntityMimicOctopus','tick','AIAttack恐吓期间给受害Mob双导航/MoveControl并清它target；近距变形按升级形态毒刺/激光/爆炸，伤害后不以返回值限制毒，另记同步受惊对象。','攻击影响包括目标AI、移动、状态与AOE；最终许可必须覆盖全部副作用。','整段全文含末尾追击已阅读，只计嵌套AIAttack.tick，外层未完整读的激光tick不计。',1169)
add('EntityMimicOctopus','creeperExplode','用自身mobAttack伤害源构建不破坏方块的原生Explosion，立即explode和finalizeExplosion。','不破坏方块不等于不伤旁观实体，宠物范围攻击要追原生爆炸命中集合。','本方法未显式盟友过滤，但未据此推定原生/事件链无保护；不引入新爆炸。')
