add('EntityTarantulaHawk','hurt','Living伤害来源是节肢且带DEBILITATING_STING就拒绝全部伤害，其他父处理。','捕获对象失能会改变对宠物的反击能力，但这只是输入保护，不保证输出目标合法。','具体物种与状态组合才计此处，不按每个状态效果参数拆条。')
add('EntityTarantulaHawk','canUse','AIMelee需活target、非坐非惧怕、非拖拽挖掘且受害者有物理/非乘客。','对已捕获或无物理目标应停普通攻击；目标许可之外还存在捕获状态前提。','仅收完整启动条件，非旁观玩家保护；本项目不新增抓取玩法。',727)
add('EntityTarantulaHawk','tick','AIMelee先判节肢麻痹/孕体与沙地，冷却盘旋；满足捕获就强制受害者骑自己，否则近远接近并在攻击进度5伤害、可能救活低血、加刺效果并广播。','实际误伤还包含强制乘骑、回血和状态，doHurtTarget拒绝不足以阻止后续附效。','源码目标null的局部风险未跑验证；不将发包或动画数值当独立参考。',738)
add('EntityTarantulaHawk','stop','AIMelee清盘旋冷却、bredBuryFlag、方向和orbitVec；仅无乘客时才清target。','捕获状态有意保留target以衔接埋藏，不能无条件认为stop已解除战斗对象。','与AIBury.stop完整清目标不同；本项目方案须按自身原租约语义，不复制捕获状态。',808)
add('EntityTarantulaHawk','canUse','AIBury要求正在拖拽且target非空，生成沙地成功才缓存buryPos并开启。','另一个goal可承接旧target继续作用，停近战不等于停止所有后续行为。','这是真实挂载的埋藏攻击链，不计普通随机游走/沙地世界生成代码。',928)
add('EntityTarantulaHawk','canContinueToUse','AIBury继续要求拖拽、digTime<200、target及buryPos非空且位置仍是沙子。','持续地形变化和期限能终止动作，但没有在此复核target活性/owner关系。','停止条件不代表安全对象许可，不将200tick作为本项目新增期限。',940)
add('EntityTarantulaHawk','stop','AIBury清digTime、挖掘/拖拽状态、普通target和lastHurtByMob。','最终动作撤销要同时清捕获旗标与历史反击对象，防旧目标重新触发。','是否恢复受害者noPhysics在别处，本方法没有做，不能宣称全部受害者状态已恢复。',951)
add('EntityTarantulaHawk','tick','近沙地进入digging并记受害者位置；挖掘时设target.noPhysics、踢乘客、逐tick将其向下移3格，自己导航回起点。','没有伤害调用也能强制修改旁观实体物理和位置，过滤必须早于这些动作。','未验证原模组其他回收路径；此处只观察完整埋藏执行方法，不改本项目移动。',959)
